import{_ as o,l as r,o as e,c as l,v as t,p as h,x as n,d as s,i as u,S as m}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"经济显著性 vs 统计显著性","description":"","frontmatter":{"title":"经济显著性 vs 统计显著性","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/econ-vs-stat-sig.md","filePath":"quant/econ-vs-stat-sig.md","lastUpdated":1789023840000}'),p={name:"quant/econ-vs-stat-sig.md"};function E(d,a,A,c,f,B){const i=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="经济显著性-vs-统计显著性" tabindex="-1">经济显著性 vs 统计显著性 <a class="header-anchor" href="#经济显著性-vs-统计显著性" aria-label="Permalink to &quot;经济显著性 vs 统计显著性&quot;">​</a></h1><div class="epigraph"><p>即便复制成功的异常，其经济幅度也往往远小于原文所报；市场比先前文献承认的更有效。</p><footer>—— Hou, Xue and Zhang, Replicating Anomalies, Review of Financial Studies, 2020</footer></div><p>Harvey、Liu 与 Zhu 把发现的门槛从 \\(|t|\\gt 2\\) 抬到大约 3，管的是假阳性。<a href="/quant/multiple-testing-factors">多重检验</a> 与<a href="/quant/deflated-sharpe">紧缩夏普</a> 沿着同一条统计轴加严。经济显著性问的是另一条轴：这个效应以可交易的美元计有多大，扣完成本、换到市值加权、避开微盘之后还剩多少。t 可以很高——长样本、高换手、等权微盘都能制造显著——而投资者无法以有意义的规模捕获。Hou–Xue–Zhang 复制 452 个异常：65% 过不了 \\(|t|\\ge 1.96\\) 的单次门槛，多重检验门槛 2.78 时失败率 82%，交易摩擦类失败约 96%；即便活下来的，幅度也小于原文。McLean–Pontiff 的发表后剩余收益，同样要过成本与容量，才能叫经济显著。两条轴都通过，才进入<a href="/quant/live-drift-monitor">实盘漂移监测</a>的名单；只通过统计轴，是论文，不是产品。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>统计显著性回答：在原假设「没有效应」下，看到这么大的样本均值有多稀有。经济显著性回答：效应的量级是否大到覆盖摩擦、支撑容量、并在可投资宇宙里仍然存在。二者可以分离。长样本里每月 10 个基点的等权溢价可以 t 很大，但市值加权后消失——Hou–Xue–Zhang 把这件事写成复制标准：NYSE 断点、市值加权、控制微盘。反过来，短样本里一个大的事件溢价可以经济上诱人但 t 不够，这时缺的是证据，不是美元。</p><p>资产定价文献长期用 t 当发现的货币。期刊喜欢显著，等权与微盘提供显著，于是报告的异常被推向不可交易的角落。McLean–Pontiff 看到样本外与发表后收益下降，部分是偏差，部分是交易；下降之后剩下的那截，仍要用美元与深度去度量。把「发表后仍显著」直接读成「还能做」，漏了幅度已经可能低于有效价差。</p><h3 id="微盘与等权是统计显著性的免费杠杆" tabindex="-1">微盘与等权是统计显著性的免费杠杆 <a class="header-anchor" href="#微盘与等权是统计显著性的免费杠杆" aria-label="Permalink to &quot;微盘与等权是统计显著性的免费杠杆&quot;">​</a></h3><p>美国市场上，微盘占名字的多数、占市值的少数。等权多空把检验的有效样本推向最贵、最浅的名字；NYSE 断点把分位切在可交易的一侧，市值加权把检验推向有容量的一侧。Hou–Xue–Zhang 表明：手续一换，多数异常的 t 掉到 2 以下；摩擦变量尤其如此，因为它们度量的就是不可交易性。Harvey–Liu–Zhu 的 t&gt;3 在等权微盘上仍然可能被刷出来，所以统计门槛不能替代加权手续。复制成功的定义应同时声明：宇宙、加权、断点、持有期、以及是否扣费。</p><p><span class="marginnote">A 股的「统计显著」同样会被次新、ST、涨跌停不可买的名字抬高。经济显著必须在可买可卖、涨跌停外、借券可获得的子集上重算。把不可交易日的收益记进 t，是把停牌当 alpha。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最低限度的报告应并排四列：等权未扣费 t 与月均收益；市值加权未扣费；市值加权扣费；在目标规模 \\(A\\) 下的 \\(\\mu_{\\mathrm{net}}(A)\\)。Hou–Xue–Zhang 的单次门槛 1.96 与多重门槛 2.78（约对应他们校准的 5%）写在前两列；后两列用保本成本与<a href="/quant/cost-mc-sensitivity">费用 MC</a> 的 \\(\\mathrm{P}(\\mu_{\\mathrm{net}}\\gt 0)\\)。McLean–Pontiff 的发表后窗口单独成行：同一四列，看幅度而不是只看是否仍异于零。</p><p>经济幅度的单位要统一成投资者能理解的量：每单位跟踪误差的超额、每单位换手的超额、以及在声明参与率下可部署的名义。Grinold 的 IR 分解里，IC 高但广度来自不可重复的日频噪声，经济上不是广度。Lo（2002）对夏普抽样误差的警告在这里同样适用：短实盘路径的高夏普没有经济解释力。</p><p>与风险模型对齐。若加权后的溢价被 q-因子或五因子吃掉，见 <a href="/quant/q-factor-hxz">Hou–Xue–Zhang q-因子</a>，它更接近风险补偿而不是可耗尽的错误定价。经济显著仍可能成立——投资者可以持有该风险——但叙事要从「发现了 alpha」改成「承担了哪一种系统性暴露」。错误定价叙事必须在风险调整后、成本后、容量内同时成立。</p><h3 id="把「显著」写成决策规则而不是星号" tabindex="-1">把「显著」写成决策规则而不是星号 <a class="header-anchor" href="#把「显著」写成决策规则而不是星号" aria-label="Permalink to &quot;把「显著」写成决策规则而不是星号&quot;">​</a></h3><p>研究准入：统计轴用 HLZ 或紧缩夏普，经济轴用加权后月均收益相对有效价差与冲击预测的倍数。两边都过，才进模拟。模拟准入：在声明的 \\(A\\) 与 \\(p_{\\max}\\) 下 \\(\\mu_{\\mathrm{net}}\\) 的 MC 左尾过零。实盘准入：小规模成交回报验证冲击，而不是用更长的 t 去代替。Arnott、Harvey 与 Markowitz 的回测协议强调时间顺序；经济显著性是协议里「值得按该顺序去试」的门槛，不是试完之后贴上的标签。</p><p><span class="marginnote">t=3 且月均 5bp、换手 40% 的日频信号，统计上像发现，经济上往往是噪声交易。t=2.2 且月均 40bp、换手 8%、市值加权仍在的季度信号，统计上不够 HLZ，经济上更值得用更多样本去确认。门槛是向量，不是标量。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>t 统计量 \\(t=\\hat\\mu/(\\hat\\sigma/\\sqrt{n})\\) 对 \\(n\\) 敏感，对 \\(\\hat\\mu\\) 的美元意义不敏感。高频再平衡把 \\(n\\) 做大，也把换手做大；分子若来自价差的错误计量，t 会漂亮地指向一个不能交易的方向。经济显著性把分子换成扣费后、把分母换成可部署风险，相当于用投资者的约束重写检验。Hou–Xue–Zhang 的加权与微盘控制，是把检验的测度从「名字的计数测度」换成「市值测度」。McLean–Pontiff 的发表后下降，是把测度再换成「套利资本进入之后的测度」。每一次换测度，许多星号消失。</p><p>拥挤改变经济显著性的速度。统计显著的公开信号吸引资金，幅度被交易掉，见<a href="/quant/crowded-alpha-decay">拥挤 alpha 衰减</a>。剩余若只存在于最贵的名字上，统计上可能仍异于零（因为那些名字波动大、t 仍可观），经济上容量已经耗尽。因此经济显著必须带规模：\\(\\mu_{\\mathrm{net}}(A)\\) 而不是 \\(\\mu_{\\mathrm{net}}(0)\\)。</p><h3 id="复制失败不等于效应为零" tabindex="-1">复制失败不等于效应为零 <a class="header-anchor" href="#复制失败不等于效应为零" aria-label="Permalink to &quot;复制失败不等于效应为零&quot;">​</a></h3><p>Hou–Xue–Zhang 拒绝的是「按他们的手续仍显著」，不是「原文的等权回测算错了」。原文可能在当时的宇宙与加权下确实有 t。经济问题是：那个 t 对应的投资计划今天是否可执行。反过来，复制成功且幅度仍可观的异常，仍要过成本 MC 与拥挤代理。统计与经济两轴是过滤，不是存在性的形而上学。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>多重检验门槛随尝试次数变，经济门槛随身份变：做市账户与养老金的 \\(c\\) 不同，\\(A\\) 不同。不要用机构短fall 去给零售策略签发经济显著，也不要用学术价差去宣判机构策略不可做。样本起止会同时改变 t 与幅度；预指定窗口，避免为了 t 或为了美元去挑区间。</p><p>不要用「我们报告了经济幅度」当借口回避多重检验：大的点估计可以是一次幸运。也不要用 t&gt;3 当借口回避加权：微盘上等权的 t=4 仍然没有容量。LLM 挖掘把尝试次数再抬一个数量级，统计轴必须更严；同时生成器偏好文献里已经拥挤的模板，经济轴必须看相关与容量，见 <a href="/quant/alpha-gpt-mining">Alpha-GPT</a> 与 <a href="/quant/hubble-alpha-agent">Hubble</a>。</p><p><span class="marginnote">出处：Hou, Xue and Zhang, <em>Replicating Anomalies</em>, <em>RFS</em>, 2020；McLean and Pontiff, <em>JF</em>, 2016；Harvey, Liu and Zhu, <em>RFS</em>, 2016；Novy-Marx and Velikov, <em>RFS</em>, 2016。回测协议见 Arnott, Harvey and Markowitz, <em>JFDS</em>, 2019。夏普抽样误差见 Lo, <em>FAJ</em>, 2002。</span></p>',25)),(e(),h(m,null,{default:n(()=>[u(i,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E7%AD%89%E6%9D%83%20%2F%20%E5%BE%AE%E7%9B%98%20%2F%20%E6%9C%AA%E6%89%A3%E8%B4%B9%22%5D%20--%3E%20T%5B%22%E7%BB%9F%E8%AE%A1%E8%BD%B4%EF%BC%9At%20%2F%20DSR%20%2F%20HLZ%22%5D%0A%20%20RAW%20--%3E%20HXZ%5B%22NYSE%20%E6%96%AD%E7%82%B9%20%C2%B7%20%E5%B8%82%E5%80%BC%E5%8A%A0%E6%9D%83%22%5D%0A%20%20HXZ%20--%3E%20AMP%5B%22%E7%BB%8F%E6%B5%8E%E5%B9%85%E5%BA%A6%22%5D%0A%20%20AMP%20--%3E%20COST%5B%22%E6%89%A3%E8%B4%B9%20%C2%B7%20%E6%88%90%E6%9C%AC%20MC%22%5D%0A%20%20MP%5B%22%E5%8F%91%E8%A1%A8%E5%90%8E%E6%8A%98%E6%89%A3%22%5D%20--%3E%20COST%0A%20%20COST%20--%3E%20NET%5B%22%CE%BC_net(A)%22%5D%0A%20%20T%20--%3E%20G%7B%22%E4%B8%A4%E8%BD%B4%E9%83%BD%E8%BF%87%3F%22%7D%0A%20%20NET%20--%3E%20G%0A%20%20G%20--%3E%7C%E5%90%A6%7C%20DROP%5B%22%E4%B8%8D%E8%BF%9B%E6%A8%A1%E6%8B%9F%22%5D%0A%20%20G%20--%3E%7C%E6%98%AF%7C%20SIM%5B%22%E6%A8%A1%E6%8B%9F%E4%B8%8E%E5%B0%8F%E8%A7%84%E6%A8%A1%E5%AE%9E%E7%9B%98%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>统计显著回答稀有，经济显著回答可交易的美元、加权宇宙与容量；星号不能代替幅度。</li><li>Hou–Xue–Zhang：可交易加权下多数异常复制失败，活下来的幅度也更小；摩擦类尤其不是 alpha。</li><li>McLean–Pontiff 的发表后剩余收益必须再过成本与 \\(\\mu_{\\mathrm{net}}(A)\\)，才能叫经济显著。</li><li>准入规则应是向量：HLZ/DSR 与加权扣费后的左尾过零同时成立。</li><li>微盘等权把 t 当免费杠杆；换测度之后许多发现消失。</li><li>出处：Hou–Xue–Zhang, <em>RFS</em>, 2020；McLean–Pontiff, <em>JF</em>, 2016；Harvey–Liu–Zhu, <em>RFS</em>, 2016；Novy-Marx–Velikov, <em>RFS</em>, 2016。</li></ul>',2))])}const q=o(p,[["render",E]]);export{g as __pageData,q as default};
